'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{execFileSync}=require('node:child_process'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const repo=path.resolve(__dirname,'../..'),root=process.env.ADHESIONS_ORGANISATIONS_ASSET_DIR||repo,read=f=>fs.readFileSync(path.join(root,f),'utf8'),old=execFileSync('git',['show','7a52048ef85fc931f3fececa25af5fee2ee35778:plateau-organisations-quetes.js'],{cwd:repo,encoding:'utf8',maxBuffer:4e6}),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'],names=['ouvrirDemandesAdhesion','ouvrirInviterMembreOrga'];
const selected=s=>parse(s).body.filter(n=>n.type==='FunctionDeclaration'&&names.includes(n.id.name)).map(n=>s.slice(n.start,n.end)).join('\n'),escapeSource=(()=>{const s=read('forum.js'),n=parse(s).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='escapeHtmlText');return s.slice(n.start,n.end);})();
const orga=(more={})=>({id:'fixture',nom:'Organisation libre',chef:'Alice',type:'politique',visible:false,country_origine:'republic',membres:[{nom:'Déjà Membre'}],invitationsEnvoyees:[{nom:'Déjà Invité'}],demandesAdhesion:[{nom:'Bob',date:2},{nom:'Camille',date:20}],...more});
const requestCases=[{id:'chef'},{id:'autre joueur',char:{name:'Visiteur'}},{id:'sans personnage',char:null},{id:'vide',orga:orga({demandesAdhesion:[]})},{id:'champ absent',orga:orga({demandesAdhesion:undefined})},{id:'type inconnu',orga:orga({type:'inconnu'})},{id:'jour zéro',orga:orga({demandesAdhesion:[{nom:'Bob',date:0}]})},{id:'absente',orga:null}].map(c=>({mode:'requests',orga:orga(),char:{name:'Alice'},...c}));
const people=[{name:'Alice',country:'republic'},{name:'Étranger',country:'soviet'},{name:'Déjà Membre',country:'republic'},{name:'Déjà Invité',country:'republic'},{name:'Bob',country:'republic'},{name:'Camille',country:'republic'}];
const inviteCases=[{id:'filtrage'},{id:'absente',orga:null},{id:'autre joueur',char:{name:'Visiteur'}},{id:'sans personnage',char:null},{id:'publique',orga:orga({visible:true})},{id:'vide',people:[]},{id:'erreur',query:'error'},{id:'sans helper',query:'absent'},{id:'tous exclus',people:people.slice(0,4)},{id:'sans pays origine',orga:orga({country_origine:undefined})}].map(c=>({mode:'invite',orga:orga(),char:{name:'Alice'},people,...c}));
async function setup(page,before=false){await page.route('**/*',r=>r.abort());await page.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><div id="modal-postes" class="modal-overlay"><div class="modal-box"><div class="modal-header"><div id="postes-modal-title" class="modal-title"></div><button class="modal-close" aria-label="Fermer">×</button></div><div id="postes-body" class="modal-body"></div></div></div></body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});await page.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.TYPES_ORGANISATIONS={politique:{grades:{republic:['Membre','Chef']}}};window.state={country:'republic',pa:12,arg:4000,inventory:[{id:'intact'}],progression:{stage:3}};window.calls=[];window.reads=[];window.getOrgaById=id=>{reads.push(['getOrgaById',id]);return state.orga;};for(const f of ['accepterAdhesion','refuserAdhesion'])window[f]=(...args)=>calls.push([f,...args]);window.envoyerInvitationOrga=(...args)=>calls.push(['envoyerInvitationOrga',...args,document.getElementById('invite-orga-select').value]);for(const f of ['fetch','sbRpc','saveState','deduireCoutOrdre'])window[f]=(...args)=>{calls.push([f,...args]);throw Error('Appel métier interdit');};window.snapshot=()=>JSON.stringify({state,calls,reads});window.visible=()=>({title:document.getElementById('postes-modal-title').textContent,body:document.getElementById('postes-body').textContent,buttons:[...document.querySelectorAll('#postes-body button')].map(e=>e.textContent),options:[...document.querySelectorAll('#invite-orga-select option')].map(e=>[e.value,e.textContent]),open:document.getElementById('modal-postes').className,state:JSON.stringify(state),reads});document.querySelector('.modal-close').onclick=()=>document.getElementById('modal-postes').classList.remove('open');});for(const f of ['i18n/resources.js','i18n/plateau-resources.js','i18n/sovarka-droits-resources.js','i18n/sovarka-partis-resources.js','i18n/organization-admissions-resources.js','i18n/plateau-init.js'])await page.addScriptTag({content:read(f)});await page.addScriptTag({content:escapeSource+'\n'+selected(before?old:read('plateau-organisations-quetes.js'))});await page.evaluate(()=>i18next.changeLanguage('fr'));}
async function open(page,c){return page.evaluate(async c=>{state.orga=c.orga;state.char=c.char;document.getElementById('postes-modal-title').textContent='Avant';document.getElementById('postes-body').textContent='Avant';document.getElementById('modal-postes').classList.remove('open');window.sbListPersonnages=c.query==='absent'?undefined:()=>{reads.push(['sbListPersonnages']);if(c.query==='error')return Promise.reject(Error('fixture'));return Promise.resolve(c.people);};if(c.mode==='requests')ouvrirDemandesAdhesion(c.orga?.id||'absente');else await ouvrirInviterMembreOrga(c.orga?.id||'absente');return visible();},c);}
async function translated(page,lang){await page.evaluate(l=>i18next.changeLanguage(l),lang);for(const node of await page.locator('#modal-postes [data-i18n]').all()){const key=await node.getAttribute('data-i18n');assert.equal(await node.textContent(),await page.evaluate(k=>i18next.t(k),key));assert.equal(await node.getAttribute('dir'),lang==='ar'?'rtl':null);}assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await page.locator('.modal-box').evaluate(e=>e.scrollWidth>e.clientWidth),false);}
test('adhésions : neuf langues, français/accès/filtrage identiques, attente et sélection préservées, 320/390/1280 sans dépense',async()=>{const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0;try{for(const width of [320,390,1280]){const p=await browser.newPage({viewport:{width,height:900}}),before=await browser.newPage({viewport:{width,height:900}}),errors=[],requests=[];p.on('pageerror',e=>errors.push(String(e)));p.on('request',r=>requests.push(r.url()));await setup(p);await setup(before,true);
for(const c of [...requestCases,...inviteCases]){for(const page of [p,before])await page.evaluate(()=>i18next.changeLanguage('fr'));assert.deepEqual(await open(p,c),await open(before,c),c.mode+'/'+c.id+' : français/données/lectures identiques');if(await p.locator('#invite-orga-select').count())await p.locator('#invite-orga-select').selectOption('Camille');const snapshot=await p.evaluate(()=>snapshot()),select=await p.locator('#invite-orga-select').count()?await p.locator('#invite-orga-select').inputValue():null;for(const lang of langs){await translated(p,lang);assert.equal(await p.evaluate(()=>snapshot()),snapshot);if(select)assert.equal(await p.locator('#invite-orga-select').inputValue(),select);switches++;}}
// Même séquence intentionnelle de clic et clavier que sur main.
for(const page of [p,before]){await open(page,requestCases[0]);for(let i=0;i<2;i++){await page.locator('#postes-body button').nth(i).click();await page.locator('#postes-body button').nth(i).focus();await page.keyboard.press('Enter');}await open(page,inviteCases[0]);await page.locator('#invite-orga-select').selectOption('Camille');await page.locator('#postes-body button').click();}assert.deepEqual(await p.evaluate(()=>calls),await before.evaluate(()=>calls));assert.equal((await p.evaluate(()=>calls)).length,5);
// Attente réelle : même requête, aucune nouvelle lecture pendant les neuf bascules.
for(const page of [p,before]){await open(page,inviteCases[0]);await page.evaluate(()=>{sbListPersonnages=()=>{reads.push(['attente']);return new Promise(r=>window.release=r);};window.pending=ouvrirInviterMembreOrga('fixture');});}await p.evaluate(()=>i18next.changeLanguage('fr'));assert.deepEqual(await p.evaluate(()=>visible()),await before.evaluate(()=>visible()));const loading=await p.evaluate(()=>snapshot());for(const lang of langs){await translated(p,lang);assert.equal(await p.evaluate(()=>snapshot()),loading);switches++;}for(const page of [p,before])await page.evaluate(async()=>{release([{name:'Bob',country:'republic'},{name:'Camille',country:'republic'}]);await pending;});await p.locator('#invite-orga-select').selectOption('Camille');const selected=await p.evaluate(()=>snapshot());for(const lang of langs){await translated(p,lang);assert.equal(await p.locator('#invite-orga-select').inputValue(),'Camille');assert.equal(await p.evaluate(()=>snapshot()),selected);}
const name=`O'Brien "<span data-i18n="toastTitles.error">原 اسم</span>`,group='<b>Organisation 原 اسم</b>',id=`groupe'"`;
await open(p,{...requestCases[0],orga:orga({id,nom:group,demandesAdhesion:[{nom:name,date:'42 & 43'}]})});for(const lang of langs){await translated(p,lang);assert.ok((await p.locator('#postes-body').textContent()).includes(name));assert.ok((await p.locator('#postes-modal-title').textContent()).includes(group));assert.equal(await p.locator('#postes-body [data-i18n="toastTitles.error"],#postes-modal-title b').count(),0);}await p.locator('#postes-body button').first().click();assert.deepEqual(await p.evaluate(()=>calls.at(-1)),['accepterAdhesion',id,name]);
await open(p,{...inviteCases[0],orga:orga({id,nom:group}),people:[{name,country:'republic'}]});for(const lang of langs){await translated(p,lang);assert.equal(await p.locator('#invite-orga-select').inputValue(),name);assert.equal(await p.locator('#invite-orga-select option').textContent(),name);}await p.locator('#postes-body button').click();assert.deepEqual(await p.evaluate(()=>calls.at(-1)),['envoyerInvitationOrga',id,name]);
await open(p,{...requestCases[0],orga:orga({demandesAdhesion:Array.from({length:40},(_,i)=>({nom:'Personnage '+i,date:i}))})});await p.locator('.hg-organisations > div').nth(20).scrollIntoViewIfNeeded();await p.evaluate(()=>{window.kept=document.querySelector('.hg-organisations').children[20];});const scrolled=await p.evaluate(()=>snapshot());for(const lang of langs){await translated(p,lang);assert.equal(await p.evaluate(()=>snapshot()),scrolled);assert.equal(await p.evaluate(()=>kept===document.querySelector('.hg-organisations').children[20]),true);assert.ok(await p.locator('.modal-box').evaluate(e=>e.scrollTop)>0);}
for(let i=0;i<3;i++){await open(p,inviteCases[0]);await p.locator('.modal-close').click();const snap=await p.evaluate(()=>snapshot());await p.evaluate(()=>i18next.changeLanguage('ar'));assert.equal(await p.locator('#modal-postes').evaluate(e=>e.classList.contains('open')),false);assert.equal(await p.evaluate(()=>snapshot()),snap);}
await p.evaluate(()=>{document.getElementById('postes-modal-title').textContent='Fenêtre voisine';document.getElementById('postes-body').textContent='Autre corps';});await p.evaluate(()=>i18next.changeLanguage('de'));assert.equal(await p.locator('#postes-modal-title').textContent(),'Fenêtre voisine');await p.evaluate(()=>{delete i18next.getResourceBundle('de','translation').organizationAdmissions;});await open(p,inviteCases[0]);assert.equal(await p.locator('#postes-body button').textContent(),"Envoyer l'invitation");await p.evaluate(()=>{window.RPI18nPlateau=undefined;});const fallback=await open(p,inviteCases[0]);assert.equal(fallback.title,'✉️ Inviter — Organisation libre');assert.ok(fallback.body.includes("L'invitation est privée"));assert.deepEqual(errors,[]);assert.deepEqual(requests,[]);await p.close();await before.close();}assert.equal(switches,513);console.log('18 états, attente comprise : 513 bascules ; six clés et quatre réemplois.');}finally{await browser.close();}});
